// Sistema de gerenciamento de estado da conversa
const telefone = $input.item.json.telefone_cliente;
const mensagem = $input.item.json.mensagem_usuario;

// Simular banco de dados de sessões (em produção, usar Redis/MongoDB)
if (!$execution.customData) {
  $execution.customData = {};
}

if (!$execution.customData[telefone]) {
  $execution.customData[telefone] = {
    etapa: 'inicio',
    dados: {}
  };
}

const sessao = $execution.customData[telefone];
let proximaEtapa = sessao.etapa;
let resposta = '';
let concluido = false;

// Máquina de estados do fluxo
switch(sessao.etapa) {
  case 'inicio':
    resposta = `Olá! 👋 Bem-vindo à nossa imobiliária!\n\nVou te ajudar a encontrar o imóvel perfeito.\n\nVocê está buscando:\n\n1️⃣ Aluguel\n2️⃣ Compra\n\nResponda com o número:`;
    proximaEtapa = 'tipo_negocio';
    break;

  case 'tipo_negocio':
    if (mensagem === '1') {
      sessao.dados.tipo = 'aluguel';
      resposta = `Ótimo! Aluguel selecionado.\n\nQual sua faixa de orçamento mensal?\n\n1️⃣ Até R$ 1.500\n2️⃣ R$ 1.500 a R$ 3.000\n3️⃣ R$ 3.000 a R$ 5.000\n4️⃣ Acima de R$ 5.000\n\nResponda com o número:`;
    } else if (mensagem === '2') {
      sessao.dados.tipo = 'compra';
      resposta = `Ótimo! Compra selecionada.\n\nQual sua faixa de investimento?\n\n1️⃣ Até R$ 500.000\n2️⃣ R$ 500.000 a R$ 1.000.000\n3️⃣ R$ 1.000.000 a R$ 2.000.000\n4️⃣ Acima de R$ 2.000.000\n\nResponda com o número:`;
    } else {
      resposta = 'Por favor, responda com 1 ou 2.';
      proximaEtapa = 'tipo_negocio';
      break;
    }
    proximaEtapa = 'orcamento';
    break;

  case 'orcamento':
    const faixas = {
      '1': sessao.dados.tipo === 'aluguel' ? 'ate_1500' : 'ate_500k',
      '2': sessao.dados.tipo === 'aluguel' ? '1500_3000' : '500k_1m',
      '3': sessao.dados.tipo === 'aluguel' ? '3000_5000' : '1m_2m',
      '4': sessao.dados.tipo === 'aluguel' ? 'acima_5000' : 'acima_2m'
    };

    if (faixas[mensagem]) {
      sessao.dados.faixa_preco = faixas[mensagem];
      resposta = `Perfeito! 💰\n\nQuantos dormitórios você precisa?\n\n1️⃣ 1 dormitório\n2️⃣ 2 dormitórios\n3️⃣ 3 dormitórios\n4️⃣ 4 ou mais\n\nResponda com o número:`;
      proximaEtapa = 'dormitorios';
    } else {
      resposta = 'Por favor, escolha uma opção entre 1 e 4.';
    }
    break;

  case 'dormitorios':
    if (['1', '2', '3', '4'].includes(mensagem)) {
      sessao.dados.dormitorios = mensagem === '4' ? '4+' : mensagem;
      resposta = `Ótimo! 🛏️\n\nTipo de imóvel:\n\n1️⃣ Apartamento\n2️⃣ Casa térrea\n3️⃣ Sobrado\n4️⃣ Cobertura\n5️⃣ Qualquer tipo\n\nResponda com o número:`;
      proximaEtapa = 'tipo_imovel';
    } else {
      resposta = 'Por favor, escolha uma opção entre 1 e 4.';
    }
    break;

  case 'tipo_imovel':
    const tipos = {
      '1': 'apartamento',
      '2': 'casa_terrea',
      '3': 'sobrado',
      '4': 'cobertura',
      '5': 'qualquer'
    };

    if (tipos[mensagem]) {
      sessao.dados.tipo_imovel = tipos[mensagem];
      resposta = `Legal! 🏠\n\nPreferência de sala:\n\n1️⃣ Sala integrada (conceito aberto)\n2️⃣ Sala separada\n3️⃣ Tanto faz\n\nResponda com o número:`;
      proximaEtapa = 'sala';
    } else {
      resposta = 'Por favor, escolha uma opção entre 1 e 5.';
    }
    break;

  case 'sala':
    const tiposSala = {
      '1': 'integrada',
      '2': 'separada',
      '3': 'tanto_faz'
    };

    if (tiposSala[mensagem]) {
      sessao.dados.tipo_sala = tiposSala[mensagem];
      resposta = `Entendido! 🚗\n\nVagas de garagem:\n\n1️⃣ 1 vaga\n2️⃣ 2 vagas\n3️⃣ 3 ou mais vagas\n4️⃣ Não preciso\n\nResponda com o número:`;
      proximaEtapa = 'vagas';
    } else {
      resposta = 'Por favor, escolha uma opção entre 1 e 3.';
    }
    break;

  case 'vagas':
    if (['1', '2', '3', '4'].includes(mensagem)) {
      sessao.dados.vagas = mensagem === '4' ? '0' : mensagem;
      resposta = `Ótimo! 📍\n\nPor fim, qual região você prefere?\n\nDigite o nome do bairro ou região:\n(Exemplo: Centro, Zona Sul, etc.)`;
      proximaEtapa = 'localizacao';
    } else {
      resposta = 'Por favor, escolha uma opção entre 1 e 4.';
    }
    break;

  case 'localizacao':
    sessao.dados.localizacao = mensagem;
    resposta = `Perfeito! ✅\n\nVou buscar imóveis com suas preferências:\n\n📋 Tipo: ${sessao.dados.tipo}\n💰 Faixa: ${sessao.dados.faixa_preco}\n🛏️ Dormitórios: ${sessao.dados.dormitorios}\n🏠 Tipo: ${sessao.dados.tipo_imovel}\n🪟 Sala: ${sessao.dados.tipo_sala}\n🚗 Vagas: ${sessao.dados.vagas}\n📍 Local: ${sessao.dados.localizacao}\n\nAguarde um momento...`;
    proximaEtapa = 'buscar';
    concluido = true;
    break;

  default:
    resposta = 'Erro no fluxo. Digite "reiniciar" para começar novamente.';
    if (mensagem.toLowerCase() === 'reiniciar') {
      proximaEtapa = 'inicio';
      sessao.dados = {};
    }
}

// Atualizar estado
sessao.etapa = proximaEtapa;
$execution.customData[telefone] = sessao;

return {
  telefone: telefone,
  resposta: resposta,
  etapa_atual: proximaEtapa,
  dados_coletados: sessao.dados,
  buscar_imoveis: concluido
};

// Processar resultados e montar mensagem de resposta
const dados = $input.first().json;
const imoveis = dados.imoveis || [];
const telefone = $('Lógica do Fluxo').first().json.telefone;

let mensagemFinal = '';

if (imoveis.length === 0) {
  mensagemFinal = `😔 Não encontrei imóveis disponíveis com esses critérios no momento.\n\nMas não se preocupe! Vou registrar seu interesse e nossa equipe entrará em contato quando tivermos opções.\n\n📞 Contato direto:\nTelefone: (11) 9999-9999\nEmail: contato@imobiliaria.com.br\n\nObrigado! 🏠`;
} else {
  mensagemFinal = `🎉 Encontrei ${imoveis.length} ${imoveis.length === 1 ? 'imóvel' : 'imóveis'} para você!\n\n`;

  // Adicionar detalhes de cada imóvel (máximo 3 para não ficar muito longo)
  const imoveisParaMostrar = imoveis.slice(0, 3);

  imoveisParaMostrar.forEach((imovel, index) => {
    mensagemFinal += `\n━━━━━━━━━━━━━━━━━━\n`;
    mensagemFinal += `🏡 *${imovel.titulo}*\n\n`;
    mensagemFinal += `📍 ${imovel.endereco}\n`;
    mensagemFinal += `💰 R$ ${imovel.preco.toLocaleString('pt-BR')}\n`;
    mensagemFinal += `🛏️ ${imovel.dormitorios} ${imovel.dormitorios === 1 ? 'dormitório' : 'dormitórios'}\n`;
    mensagemFinal += `🚗 ${imovel.vagas} ${imovel.vagas === 1 ? 'vaga' : 'vagas'}\n`;
    mensagemFinal += `📐 ${imovel.area_m2}m²\n`;

    if (imovel.caracteristicas) {
      if (imovel.caracteristicas.mobiliado) mensagemFinal += `✨ Mobiliado\n`;
      if (imovel.caracteristicas.aceita_pets) mensagemFinal += `🐾 Aceita pets\n`;
    }

    mensagemFinal += `\n🔗 ${imovel.link}\n`;

    if (imovel.descricao) {
      mensagemFinal += `\n${imovel.descricao.substring(0, 100)}...\n`;
    }
  });

  if (imoveis.length > 3) {
    mensagemFinal += `\n━━━━━━━━━━━━━━━━━━\n`;
    mensagemFinal += `\n➕ E mais ${imoveis.length - 3} ${imoveis.length - 3 === 1 ? 'imóvel' : 'imóveis'}!\n`;
  }

  mensagemFinal += `\n✅ Para mais informações ou agendar visita, entre em contato:\n📞 (11) 9999-9999\n\nDigite "buscar" para fazer nova busca!`;
}

return {
  telefone: telefone,
  mensagem: mensagemFinal,
  total_imoveis: imoveis.length,
  imoveis: imoveis
};
